// remove-generator.js
const fs = require("fs");
const path = require("path");

// Thư mục build của Next.js
const buildDir = path.join(__dirname, ".next", "server", "app");

// Hàm đệ quy quét file HTML
function cleanGeneratedComment(dir) {
  const files = fs.readdirSync(dir);

  files.forEach((file) => {
    const fullPath = path.join(dir, file);
    const stat = fs.statSync(fullPath);

    if (stat.isDirectory()) {
      cleanGeneratedComment(fullPath); 
    } else if (file.endsWith(".html")) {
      let content = fs.readFileSync(fullPath, "utf8");
      // Xóa comment <!-- Generated by create app -->
      content = content.replace(/<!--\s*Generated by create next app\s*-->/gi, "");
      fs.writeFileSync(fullPath, content, "utf8");
      console.log(`Đã xóa comment trong: ${fullPath}`);
    }
  });
}

cleanGeneratedComment(buildDir);
console.log("Hoàn tất xóa comment 'Generated by create next app'.");
